const caseReward = {
'3':['Perfect close, 3/3: each of you picks any card from any level for the other to do','Perfect close, 3/3: an untimed celebration kiss, then open the next case','Perfect close, 3/3: 5-minute massages each, and whoever told the key evidence goes first'],
'2':['Almost perfect, 2/3: pick a level 1–2 card for each other','Almost perfect, 2/3: hug for 1 minute, then tell each other what you loved about the other\'s thinking'],
'1':['1/3: each say which piece of evidence you explained badly, then give each other a 2-minute shoulder rub'],
'0':['Not one yet: the other picks a level 1 card for you to do, then try telling each other the evidence again']
};

// ---- build, copying every non-text field from the Thai file ----
const fail = m => { throw new Error(m); };
const same = (a, b, what) => { if (a.length !== b.length) fail(what + ': Thai has ' + a.length + ', English has ' + b.length); };
const EN = JSON.parse(JSON.stringify(TH));
EN.hub.forEach(h => { const e = hub[h.id] || fail('hub ' + h.id); Object.assign(h, e); });
const M = EN.massage, tm = TH.massage;
for (const k of ['intro', 'hotIntro']) M[k] = massage[k];
for (const k of ['prep', 'safety', 'hotPrep', 'hotRules']) { same(tm[k], massage[k], 'massage.' + k); M[k] = massage[k]; }
for (const id of Object.keys(tm.steps)) { const e = massage.steps[id] || fail('massage step ' + id); Object.assign(M.steps[id], e); }
for (const p of Object.keys(tm.poses)) M.poses[p] = massage.poses[p] || fail('pose ' + p);
same(TH.nights, nights, 'nights');
EN.nights = TH.nights.map((n, i) => { same(n.tasks, nights[i].tasks, 'night ' + i); return Object.assign({}, n, nights[i]); });
same(TH.dates, dates, 'dates');
EN.dates = TH.dates.map((d, i) => { const e = dates[i]; for (const k of ['setup', 'food', 'flow']) same(d[k], e[k], 'date ' + i + ' ' + k); return Object.assign({}, d, e, { level: d.level }); });
same(TH.cases, cases, 'cases');
EN.cases = TH.cases.map((c, i) => {
  const [t, tag, story, sus, pub, a, b, how, why, sol] = cases[i];
  same(c.sus, sus, c.id + ' suspects'); same(c.pub, pub, c.id + ' pub'); same(c.a, a, c.id + ' a'); same(c.b, b, c.id + ' b');
  same(c.how.o, how, c.id + ' how'); same(c.why.o, why, c.id + ' why');
  return { id: c.id, lv: c.lv, t, tag, story, sus: sus.map(([n, r, m]) => ({ n, r, m })), pub, a, b, who: c.who,
    how: { o: how, a: c.how.a }, why: { o: why, a: c.why.a }, sol };
});
for (const k of Object.keys(TH.caseReward)) { same(TH.caseReward[k], caseReward[k] || [], 'caseReward ' + k); }
EN.caseReward = caseReward;
fs.writeFileSync(path.join(root, 'bonus-en.json'), JSON.stringify(EN, null, 2) + '\n');
console.log('wrote bonus-en.json:', EN.cases.length, 'cases,', EN.nights.length, 'nights,', EN.dates.length, 'dates,', Object.keys(M.steps).length, 'massage steps');
